/**
 * The v2 held-out split, authored independently of the rules and evaluated once on frozen rules v2
 * (bc96115). Its misses are now known, so it is spent as independent validation and serves as
 * tuning data from then on.
 */
import type { CorpusCase } from './types.js';
import {
  crash, timeout, stale, codexUnclaimed, maxAttempts, reviewFailed,
  ciFailed, mergeConflict, prClosed, claudeResult, STDIN_WARNING, CODEX_PREAMBLE,
} from './shapes.js';

/** Join log lines. */
const L = (...lines: string[]): string => lines.join('\n');

/** A Claude stream-json assistant text line. */
const said = (text: string): string =>
  JSON.stringify({ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text }] } });

/** A Claude stream-json tool_result line. */
const tool = (content: string, isError = false): string =>
  JSON.stringify({ type: 'user', message: { role: 'user', content: [{ tool_use_id: 'toolu_01HeLd', type: 'tool_result', content, is_error: isError }] } });

/** A Codex `exec --json` event line. */
const cx = (event: object): string => JSON.stringify(event);

/** A Codex command_execution item. */
const cmd = (command: string, output: string, exitCode: number): string =>
  cx({ type: 'item.completed', item: { id: 'item_7', type: 'command_execution', command, aggregated_output: output, exit_code: exitCode, status: exitCode === 0 ? 'completed' : 'failed' } });

/** 400 passing xUnit lines that bury the one failure (longer than any reasonable scan window). */
const LEDGER_PASSES = Array.from({ length: 400 }, (_, i) =>
  `  Passed Example.Ledger.Tests.PostingTests.Posts_entry_variant_${String(i).padStart(3, '0')} [${(i % 9) + 1} ms]`);

